/* Prism — Dimension Explorer · compact dark professional theme */

:root {
  --bg: #0e1116;
  --panel: #151a22;
  --panel-2: #10141b;
  --border: #252c38;
  --border-soft: #1c222c;
  --text: #d9dee7;
  --text-dim: #8b93a3;
  --text-faint: #5c6575;
  --accent: #5aa2ff;
  --danger: #ff7a7a;
  --chip-bg: #1b2230;
  --radius: 6px;
  --row-h: 26px;
  --mono: ui-monospace, "Cascadia Mono", Consolas, monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body { height: 100%; }

body {
  background: var(--bg);
  color: var(--text);
  font: 13px/1.45 "Segoe UI", system-ui, -apple-system, sans-serif;
  display: grid;
  grid-template-rows: 46px 1fr;
  overflow: hidden;
}

/* ---------- header ---------- */

.app-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 14px;
  border-bottom: 1px solid var(--border);
  background: var(--panel-2);
}

.brand { display: flex; align-items: baseline; gap: 8px; }
.brand-mark {
  width: 12px; height: 12px; align-self: center;
  background: conic-gradient(from 210deg, #5aa2ff, #a78bfa, #f472b6, #34d399, #5aa2ff);
  border-radius: 3px;
}
.brand h1 { font-size: 15px; font-weight: 650; letter-spacing: .2px; }
.brand-sub { color: var(--text-dim); font-size: 12px; }

.dataset-meta {
  color: var(--text-dim);
  font-family: var(--mono);
  font-size: 11.5px;
  display: flex;
  gap: 14px;
}
.dataset-meta b { color: var(--text); font-weight: 600; }
.dataset-meta .meta-scope-ok b { color: #7ddba8; }
.dataset-meta .meta-scope-cut b { color: #f2c464; }

.header-actions { margin-left: auto; display: flex; align-items: center; gap: 8px; }

.kbd-hint { color: var(--text-faint); font-size: 11px; }
kbd {
  font-family: var(--mono); font-size: 10px;
  border: 1px solid var(--border); border-bottom-width: 2px;
  border-radius: 3px; padding: 0 3px; color: var(--text-dim);
}

.btn {
  background: var(--chip-bg);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
  font-size: 12px;
  padding: 3px 10px;
  cursor: pointer;
}
.btn:hover { border-color: #3a4657; background: #212a3a; }
.btn:disabled { opacity: .4; cursor: default; }
.btn-mini { font-size: 11px; padding: 1px 7px; }
.btn-danger-ghost { color: #f0a0a0; }
.btn-danger-ghost:hover { border-color: #6b3a3a; background: #2a1d1d; }

/* ---------- workspace layout ---------- */

.workspace {
  display: grid;
  grid-template-columns: 198px minmax(0, 1fr) 316px;
  gap: 1px;
  background: var(--border-soft);
  min-height: 0;
}

.panel { background: var(--panel); min-height: 0; }

/* ---------- dimension rail ---------- */

.rail { display: flex; flex-direction: column; }
.rail:focus-visible { outline: 1px solid var(--accent); outline-offset: -1px; }

.rail-head, .trail-head {
  padding: 8px 12px 6px;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--text-faint);
  display: flex;
  align-items: center;
  gap: 6px;
}
.rail-count { color: var(--text-dim); font-weight: 500; letter-spacing: 0; text-transform: none; }
.trail-head .btn-mini { margin-left: auto; }

.rail-list { flex: 1; overflow-y: auto; padding: 2px 6px 6px; }

.dim-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  text-align: left;
  background: none;
  border: 1px solid transparent;
  border-radius: var(--radius);
  color: var(--text-dim);
  font: inherit;
  font-size: 12.5px;
  padding: 4px 8px;
  margin: 1px 0;
  cursor: pointer;
}
.dim-item:hover { background: #1a2130; color: var(--text); }
.dim-item.active {
  background: color-mix(in srgb, var(--dim) 14%, transparent);
  border-color: color-mix(in srgb, var(--dim) 45%, transparent);
  color: var(--text);
}
.dim-item:focus-visible { outline: 1px solid var(--accent); outline-offset: -1px; }
.dim-dot { width: 8px; height: 8px; border-radius: 2px; background: var(--dim); flex: none; }
.dim-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dim-badge {
  font-family: var(--mono); font-size: 10px; color: var(--text-faint);
}
.dim-badge.filters {
  color: var(--dim);
  border: 1px solid color-mix(in srgb, var(--dim) 50%, transparent);
  border-radius: 8px; padding: 0 5px;
}

.rail-foot {
  padding: 8px 12px 10px;
  color: var(--text-faint);
  font-size: 10.5px;
  border-top: 1px solid var(--border-soft);
}

/* ---------- center: state strip ---------- */

.center { display: grid; grid-template-rows: auto auto 1fr; min-width: 0; min-height: 0; }

.state-strip {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  padding: 7px 12px;
  border-bottom: 1px solid var(--border-soft);
  background: var(--panel-2);
  min-height: 37px;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--chip-bg);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 2px 4px 2px 9px;
  font-size: 11.5px;
  color: var(--text);
  max-width: 320px;
}
.chip .chip-dot { width: 8px; height: 8px; border-radius: 2px; background: var(--dim, var(--accent)); flex: none; }
