.insp-stat .k { color: var(--text-faint); font-size: 10px; text-transform: uppercase; letter-spacing: .08em; }
.insp-stat .v { font-family: var(--mono); font-size: 13px; font-weight: 600; }
.insp-cross-label {
  padding: 2px 12px 4px;
  font-size: 10.5px; font-weight: 650;
  letter-spacing: .12em; text-transform: uppercase;
  color: var(--text-faint);
}
.insp-cross-label .dim-dot { display: inline-block; margin-right: 6px; }
.cross-row {
  display: grid;
  grid-template-columns: minmax(70px, 96px) 1fr 52px;
  align-items: center;
  gap: 8px;
  padding: 2px 12px;
  height: 22px;
  font-size: 11.5px;
}
.cross-row .cv { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text); }
.cross-row .cbar { height: 7px; background: #1a2029; border-radius: 3px; position: relative; overflow: hidden; }
.cross-row .cbar i { position: absolute; inset: 0 auto 0 0; background: var(--dim); border-radius: 3px; }
.cross-row .cpct { font-family: var(--mono); text-align: right; color: var(--text-dim); font-size: 10.5px; }
.insp-hint { padding: 10px 12px; color: var(--text-faint); font-size: 12px; }
.insp-hint b { color: var(--text-dim); font-weight: 600; }

/* ---------- trail ---------- */

.trail { display: flex; flex-direction: column; }
.trail-list {
  flex: 1;
  overflow-y: auto;
  list-style: none;
  padding: 2px 6px 8px;
}
.trail-item {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 3px 6px 3px 4px;
  border-radius: var(--radius);
  font-size: 11.5px;
  color: var(--text-dim);
}
.trail-item:hover { background: #1a2130; color: var(--text); }
.trail-item.base { color: var(--text-faint); cursor: default; }
.trail-item.base:hover { background: none; color: var(--text-faint); }
.trail-idx {
  font-family: var(--mono); font-size: 10px; color: var(--text-faint);
  width: 20px; text-align: right; flex: none;
}
.trail-dot { width: 7px; height: 7px; border-radius: 2px; background: var(--dim, var(--text-faint)); flex: none; }
.trail-label { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.trail-label b { color: var(--text); font-weight: 600; }
.trail-revert {
  background: none; border: 1px solid transparent; border-radius: 4px;
  color: var(--text-faint); font-size: 10.5px; padding: 1px 5px; cursor: pointer;
  visibility: hidden;
}
.trail-item:hover .trail-revert { visibility: visible; }
.trail-revert:hover { color: var(--accent); border-color: var(--border); background: #212a3a; }

.trail-empty { padding: 8px 12px; color: var(--text-faint); font-size: 11.5px; }

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: #262e3b; border-radius: 5px; border: 2px solid var(--panel); }
::-webkit-scrollbar-track { background: transparent; }

