}
.brand h1 { font-size: 15px; font-weight: 650; letter-spacing: .2px; }
.brand-sub { color: var(--text-dim); font-size: 12px; }

.dataset-meta {
  color: var(--text-dim);
  font-family: var(--mono);
  font-size: 11.5px;
  display: flex;
  gap: 14px;
}
.dataset-meta b { color: var(--text); font-weight: 600; }
.dataset-meta .meta-scope-ok b { color: #7ddba8; }
.dataset-meta .meta-scope-cut b { color: #f2c464; }

.header-actions { margin-left: auto; display: flex; align-items: center; gap: 8px; }

.kbd-hint { color: var(--text-faint); font-size: 11px; }
kbd {
  font-family: var(--mono); font-size: 10px;
  border: 1px solid var(--border); border-bottom-width: 2px;
  border-radius: 3px; padding: 0 3px; color: var(--text-dim);
}

.btn {
  background: var(--chip-bg);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
  font-size: 12px;
  padding: 3px 10px;
  cursor: pointer;
}
.btn:hover { border-color: #3a4657; background: #212a3a; }
.btn:disabled { opacity: .4; cursor: default; }
.btn-mini { font-size: 11px; padding: 1px 7px; }
.btn-danger-ghost { color: #f0a0a0; }
.btn-danger-ghost:hover { border-color: #6b3a3a; background: #2a1d1d; }

/* ---------- workspace layout ---------- */

.workspace {
  display: grid;
  grid-template-columns: 198px minmax(0, 1fr) 316px;
  gap: 1px;
  background: var(--border-soft);
  min-height: 0;
}

.panel { background: var(--panel); min-height: 0; }

/* ---------- dimension rail ---------- */

.rail { display: flex; flex-direction: column; }
.rail:focus-visible { outline: 1px solid var(--accent); outline-offset: -1px; }

.rail-head, .trail-head {
  padding: 8px 12px 6px;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--text-faint);
  display: flex;
  align-items: center;
  gap: 6px;
}
.rail-count { color: var(--text-dim); font-weight: 500; letter-spacing: 0; text-transform: none; }
.trail-head .btn-mini { margin-left: auto; }

.rail-list { flex: 1; overflow-y: auto; padding: 2px 6px 6px; }

.dim-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  text-align: left;
  background: none;
  border: 1px solid transparent;
  border-radius: var(--radius);
  color: var(--text-dim);
  font: inherit;
  font-size: 12.5px;
  padding: 4px 8px;
  margin: 1px 0;
  cursor: pointer;
}
.dim-item:hover { background: #1a2130; color: var(--text); }
.dim-item.active {
  background: color-mix(in srgb, var(--dim) 14%, transparent);
  border-color: color-mix(in srgb, var(--dim) 45%, transparent);
  color: var(--text);
}
.dim-item:focus-visible { outline: 1px solid var(--accent); outline-offset: -1px; }
.dim-dot { width: 8px; height: 8px; border-radius: 2px; background: var(--dim); flex: none; }
.dim-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dim-badge {
  font-family: var(--mono); font-size: 10px; color: var(--text-faint);
}
.dim-badge.filters {
  color: var(--dim);
  border: 1px solid color-mix(in srgb, var(--dim) 50%, transparent);
  border-radius: 8px; padding: 0 5px;
}

.rail-foot {
  padding: 8px 12px 10px;
  color: var(--text-faint);
  font-size: 10.5px;
  border-top: 1px solid var(--border-soft);
}

/* ---------- center: state strip ---------- */

.center { display: grid; grid-template-rows: auto auto 1fr; min-width: 0; min-height: 0; }

.state-strip {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  padding: 7px 12px;
  border-bottom: 1px solid var(--border-soft);
  background: var(--panel-2);
  min-height: 37px;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--chip-bg);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 2px 4px 2px 9px;
  font-size: 11.5px;
  color: var(--text);
  max-width: 320px;
}
.chip .chip-dot { width: 8px; height: 8px; border-radius: 2px; background: var(--dim, var(--accent)); flex: none; }
.chip .chip-owner { color: var(--dim, var(--accent)); font-weight: 600; }
.chip .chip-val { color: var(--text-dim); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chip .chip-kind { color: var(--text-faint); font-size: 10px; text-transform: uppercase; letter-spacing: .08em; }
.chip-x {
  background: none; border: 0; color: var(--text-faint);
  font: inherit; font-size: 12px; line-height: 1;
  padding: 2px 5px; border-radius: 999px; cursor: pointer;
}
.chip-x:hover { color: var(--danger); background: rgba(255, 122, 122, .12); }
.chip-projection { border-color: color-mix(in srgb, var(--dim, var(--accent)) 45%, transparent); }

.strip-empty { color: var(--text-faint); font-size: 11.5px; }
.strip-action { margin-left: auto; }

/* ---------- center: grid ---------- */

.grid-head {
  padding: 7px 12px;
  font-size: 12px;
  color: var(--text-dim);
  border-bottom: 1px solid var(--border-soft);
  display: flex;
  align-items: baseline;
  gap: 10px;
  white-space: nowrap;
  overflow: hidden;
}
.grid-head .gh-dim { color: var(--text); font-weight: 650; }
.grid-head .gh-dim .dim-dot { display: inline-block; margin-right: 6px; }
.grid-head .gh-scope { font-family: var(--mono); font-size: 11px; }
.grid-head .gh-scope b { color: var(--text); }

.grid-scroll { overflow: auto; position: relative; }

.proj-grid { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.proj-grid th {
  position: sticky; top: 0; z-index: 2;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
  color: var(--text-faint);
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: .1em;
  text-transform: uppercase;
  text-align: right;
  padding: 6px 12px 5px;
  white-space: nowrap;
}
.proj-grid th.col-val, .proj-grid th.col-bar { text-align: left; }
.proj-grid td {
  border-bottom: 1px solid var(--border-soft);
  padding: 3px 12px;
  height: var(--row-h);
  text-align: right;
  font-family: var(--mono);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.proj-grid td.col-val {
  font-family: inherit;
  font-size: 12.5px;
  text-align: left;
  color: var(--text);
}
.proj-grid td.col-bar { width: 190px; }

.share-bar {
  display: block;
  position: relative;
  height: 10px;
  max-width: 220px;
  background: #1a2029;
  border-radius: 3px;
  overflow: hidden;
}
.proj-grid tbody tr { cursor: pointer; }
.proj-grid tbody tr:hover { background: #1a2130; }
.proj-grid tbody tr.selected {
  background: color-mix(in srgb, var(--dim) 12%, transparent);
  box-shadow: inset 2px 0 0 var(--dim);
}
.proj-grid tbody tr.filtered-in { background: color-mix(in srgb, var(--dim) 7%, transparent); }
.proj-grid tbody tr.muted td { color: var(--text-faint); }
.proj-grid tbody tr.muted td.col-val { color: var(--text-dim); }

.share-bar {
  position: relative;
  height: 10px;
  min-width: 120px;
  background: #1a2029;
  border-radius: 3px;
  overflow: hidden;
}
.share-bar i {
  position: absolute; inset: 0 auto 0 0;
  background: linear-gradient(90deg, color-mix(in srgb, var(--dim) 55%, transparent), var(--dim));
  border-radius: 3px;
}

.row-act { display: inline-flex; gap: 3px; opacity: 0; transition: opacity .1s; }
tr:hover .row-act, tr:focus-within .row-act { opacity: 1; }
.act-btn {
  background: none;
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text-dim);
  font-size: 11px;
  line-height: 1;
  padding: 2px 5px;
  cursor: pointer;
}
.act-btn:hover { color: var(--text); border-color: #3a4657; background: #212a3a; }
.act-btn.on { color: var(--dim); border-color: color-mix(in srgb, var(--dim) 55%, transparent); }

.grid-empty, .grid-error {
  position: absolute; inset: 42px 0 0 0;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  gap: 8px; background: var(--panel);
}
.grid-empty[hidden], .grid-error[hidden] { display: none; }
.empty-title { font-size: 14px; font-weight: 600; }
.empty-sub { color: var(--text-dim); font-size: 12px; margin-bottom: 6px; }

/* ---------- side: inspector + trail ---------- */

.side {
  display: grid;
  grid-template-rows: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 1px;
  background: var(--border-soft);
  min-height: 0;
}

.inspector { overflow-y: auto; padding-bottom: 10px; }
.insp-head {
  padding: 8px 12px 6px;
  font-size: 10.5px; font-weight: 650;
  letter-spacing: .12em; text-transform: uppercase;
  color: var(--text-faint);
}
.insp-title {
  display: flex; align-items: center; gap: 8px;
  padding: 2px 12px 4px;
  font-size: 15px; font-weight: 650;
}
.insp-owner { color: var(--text-dim); font-size: 11.5px; font-weight: 500; }
.insp-scope { padding: 0 12px 8px; color: var(--text-dim); font-size: 11.5px; font-family: var(--mono); }
.insp-scope b { color: var(--text); }
.insp-stats {
  display: grid; grid-template-columns: 1fr 1fr 1fr;
  gap: 1px; background: var(--border-soft);
  border-top: 1px solid var(--border-soft);
  border-bottom: 1px solid var(--border-soft);
  margin-bottom: 8px;
}
.insp-stat { background: var(--panel); padding: 6px 12px; }
.insp-stat .k { color: var(--text-faint); font-size: 10px; text-transform: uppercase; letter-spacing: .08em; }
.insp-stat .v { font-family: var(--mono); font-size: 13px; font-weight: 600; }
.insp-cross-label {
  padding: 2px 12px 4px;
  font-size: 10.5px; font-weight: 650;
  letter-spacing: .12em; text-transform: uppercase;
  color: var(--text-faint);
}
.insp-cross-label .dim-dot { display: inline-block; margin-right: 6px; }
.cross-row {
  display: grid;
  grid-template-columns: minmax(70px, 96px) 1fr 52px;
  align-items: center;
  gap: 8px;
  padding: 2px 12px;
  height: 22px;
  font-size: 11.5px;
}
.cross-row .cv { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text); }
.cross-row .cbar { height: 7px; background: #1a2029; border-radius: 3px; position: relative; overflow: hidden; }
.cross-row .cbar i { position: absolute; inset: 0 auto 0 0; background: var(--dim); border-radius: 3px; }
.cross-row .cpct { font-family: var(--mono); text-align: right; color: var(--text-dim); font-size: 10.5px; }
.insp-hint { padding: 10px 12px; color: var(--text-faint); font-size: 12px; }
.insp-hint b { color: var(--text-dim); font-weight: 600; }

/* ---------- trail ---------- */

.trail { display: flex; flex-direction: column; }
.trail-list {
  flex: 1;
  overflow-y: auto;
  list-style: none;
  padding: 2px 6px 8px;
}
.trail-item {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 3px 6px 3px 4px;
  border-radius: var(--radius);
  font-size: 11.5px;
  color: var(--text-dim);
}
.trail-item:hover { background: #1a2130; color: var(--text); }
.trail-item.base { color: var(--text-faint); cursor: default; }
.trail-item.base:hover { background: none; color: var(--text-faint); }
.trail-idx {
  font-family: var(--mono); font-size: 10px; color: var(--text-faint);
  width: 20px; text-align: right; flex: none;
}
.trail-dot { width: 7px; height: 7px; border-radius: 2px; background: var(--dim, var(--text-faint)); flex: none; }
.trail-label { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.trail-label b { color: var(--text); font-weight: 600; }
.trail-revert {
  background: none; border: 1px solid transparent; border-radius: 4px;
  color: var(--text-faint); font-size: 10.5px; padding: 1px 5px; cursor: pointer;
  visibility: hidden;
}
.trail-item:hover .trail-revert { visibility: visible; }
.trail-revert:hover { color: var(--accent); border-color: var(--border); background: #212a3a; }

.trail-empty { padding: 8px 12px; color: var(--text-faint); font-size: 11.5px; }

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: #262e3b; border-radius: 5px; border: 2px solid var(--panel); }
::-webkit-scrollbar-track { background: transparent; }

