/* Prism — Dimension Explorer · compact dark professional theme */

:root {
  --bg: #0e1116;
  --panel: #151a22;
  --panel-2: #10141b;
  --border: #252c38;
  --border-soft: #1c222c;
  --text: #d9dee7;
  --text-dim: #97a0b0;
  --text-faint: #9099a8;
  --accent: #5aa2ff;
  --danger: #ff7a7a;
  --chip-bg: #1b2230;
  --radius: 6px;
  --row-h: 26px;
  --mono: ui-monospace, "Cascadia Mono", Consolas, monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body { height: 100%; }

body {
