Now app.js changes:
1. renderRail: dim-item buttons get tabindex=-1.
2. Rail keydown stays (roving focus among buttons via arrows) — works with tabindex=-1 since focus() programmatic works.
3. Grid keyboard: on #grid-scroll keydown — arrows highlight row, Enter/Space pin, F only-filter.
4. Trail keyboard: on #trail-panel keydown — arrows highlight item, Enter clicks revert.
5. chip-x and trail-revert get tabindex=-1.
6. CSS: .kbd-hl highlight; focus-visible outlines for .grid-scroll and .trail.

Add to app.js near events section. Also renderTrail re-creates list; highlight state can be local to handler (no persistence needed).

Implementation for grid handler:

```js
let gridHl = -1;
function hlRow(idx) {
  const rows = [...document.querySelectorAll('#proj-body tr')];
  rows.forEach(r => r.classList.remove('kbd-hl'));
  gridHl = idx;
  if (idx >= 0 && rows[gridHl]) { rows[gridHl].classList.add('kbd-hl'); rows[gridHl].scrollIntoView({ block: 'nearest' }); }
}
$('grid-scroll').addEventListener('keydown', e => {
  const rows = document.querySelectorAll('#proj-body tr');
  if (!rows.length) return;
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    hlRow(Math.min(rows.length - 1, Math.max(0, (gridHl < 0 ? (e.key === 'ArrowDown' ? -1 : 0) : gridHl) + (e.key === 'ArrowDown' ? 1 : -1))));
  } else if ((e.key === 'Enter' || e.key === ' ') && gridHl >= 0) {
    e.preventDefault(); rows[gridHl].click();
  } else if ((e.key === 'f' || e.key === 'F') && gridHl >= 0) {
    e.preventDefault(); rows[gridHl].querySelector('.act-btn')?.click();
  }
});
$('grid-scroll').addEventListener('blur', () => hlRow(-1));
```

Careful: render() rebuilds rows; highlight index lost — clear on render? rows removed anyway; gridHl may point stale — hlRow guards bounds. Reset gridHl=-1 in renderGrid.

